def parse_m(s):
    """'YYYYMMDD:VAL_MILLIONS|...' -> dict[str(YYYY-MM-DD), float USD]"""
    out = {}
    if not s:
        return out
    for part in s.split("|"):
        d, v = part.split(":")
        iso = f"{d[0:4]}-{d[4:6]}-{d[6:8]}"
        out[iso] = float(v) * 1e6
    return out
